-- GenDB engine variant Q05-always_true_conjunct: template q05.sql, kind always_true_conjunct (generated by generate.py; frozen)
SELECT
  n_name,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue
FROM customer, orders, lineitem, supplier, nation, region
WHERE
  c_custkey = o_custkey
  AND l_orderkey = o_orderkey
  AND l_suppkey = s_suppkey
  AND c_nationkey = s_nationkey
  AND s_nationkey = n_nationkey
  AND n_regionkey = r_regionkey
  AND r_name = $1
  AND o_orderdate >= $2
  AND o_orderdate < $2 + INTERVAL '1 YEAR'
  AND c_custkey = c_custkey
GROUP BY
  n_name
ORDER BY
  revenue DESC
